commands.command:
set -eu
case "$NODE_NAME" in
  node1) peers='node2 node3' ;;
  node2) peers='node1 node3' ;;
  node3) peers='node1 node2' ;;
  *) exit 1 ;;
esac
printf 'SOURCE=%s\n' "$NODE_NAME"
for peer in $peers; do
  printf 'TARGET=%s ' "$peer"
  sudo -u clusterops -H -- ssh -o BatchMode=yes -o StrictHostKeyChecking=yes "$peer" 'printf "REMOTE_HOST=%s REMOTE_USER=%s SSH_CONNECTION=%s\n" "$(hostname)" "$(id -un)" "$SSH_CONNECTION"'
done

